urlset:
{%- assign core = "/,/publications/,/blog/,/repositories/" | split: "," -%}
{%- for u in core %}

  {{ u | absolute_url }}
  {{ site.time | date_to_xmlschema }}
  {% if u == '/' or u == '/blog/' %}weekly{% else %}monthly{% endif %}
  {% if u == '/' %}1.0{% else %}0.8{% endif %}

{%- endfor %}
{%- for post in site.posts %}

  {{ post.url | absolute_url }}
  {{ post.last_modified_at | default: post.date | date_to_xmlschema }}
  monthly
  0.7

{%- endfor %}
